<?php
declare(strict_types=1);

namespace HolyFace\Api\Services;

use HolyFace\Api\Database\Connection;
use PDO;

/**
 * Official cards are generated by the class adviser and released at PTC.
 * Students only see a card after released_at is set.
 */
final class ReportCardService
{
    public function hasCardForUser(int $userId): bool
    {
        return $this->cardForUser($userId) !== null;
    }

    /** @return array<string, mixed>|null */
    public function cardForUser(int $userId): ?array
    {
        $pdo = Connection::get();
        $stmt = $pdo->prepare(
            'SELECT orc.payload_json
             FROM official_report_cards orc
             INNER JOIN enrollments e ON e.id = orc.enrollment_id
             INNER JOIN students s ON s.id = e.student_id
             WHERE s.user_id = ? AND e.status IN ("enrolled","completed")
               AND orc.released_at IS NOT NULL
             ORDER BY orc.released_at DESC
             LIMIT 1'
        );
        $stmt->execute([$userId]);
        $json = $stmt->fetchColumn();
        if (!$json) {
            return null;
        }
        $data = json_decode((string) $json, true);
        return is_array($data) ? $data : null;
    }

    /** @return array<string, mixed> */
    public function progressForUser(int $userId): array
    {
        $pdo = Connection::get();
        $stmt = $pdo->prepare(
            'SELECT e.id AS enrollment_id, orc.id AS card_id, orc.released_at
             FROM enrollments e
             INNER JOIN students s ON s.id = e.student_id
             LEFT JOIN official_report_cards orc ON orc.enrollment_id = e.id
             WHERE s.user_id = ? AND e.status IN ("enrolled","completed")
             ORDER BY e.id DESC
             LIMIT 1'
        );
        $stmt->execute([$userId]);
        $row = $stmt->fetch(PDO::FETCH_ASSOC);
        if (!$row) {
            return ['total' => 0, 'submitted' => 0, 'missing' => [], 'generated' => false, 'released' => false];
        }

        $subjects = $this->subjectStatus((int) $row['enrollment_id']);
        $missing = [];
        $submitted = 0;
        foreach ($subjects as $sub) {
            if ($sub['ready']) {
                $submitted++;
            } else {
                $missing[] = $sub['title'];
            }
        }
        return [
            'total' => count($subjects),
            'submitted' => $submitted,
            'missing' => $missing,
            'generated' => !empty($row['card_id']),
            'released' => !empty($row['released_at']),
        ];
    }

    /** @return array{ready:int,waiting:int} */
    public function readyCountForClass(int $csaId): array
    {
        $pdo = Connection::get();
        $stmt = $pdo->prepare(
            'SELECT e.id AS enrollment_id
             FROM enrollments e
             INNER JOIN class_subject_assignments csa ON csa.class_section_id = e.class_section_id
             WHERE csa.id = ? AND e.status = "enrolled"'
        );
        $stmt->execute([$csaId]);
        $ready = 0;
        $waiting = 0;
        foreach ($stmt->fetchAll(PDO::FETCH_ASSOC) as $row) {
            if ($this->allSubjectsSubmitted((int) $row['enrollment_id'])) {
                $ready++;
            } else {
                $waiting++;
            }
        }
        return ['ready' => $ready, 'waiting' => $waiting];
    }

    /** @return array{generated:int,waiting:int} */
    public function generateForSection(int $sectionId, int $actorId): array
    {
        $pdo = Connection::get();
        $stmt = $pdo->prepare(
            'SELECT id FROM enrollments WHERE class_section_id = ? AND status = "enrolled"'
        );
        $stmt->execute([$sectionId]);
        $generated = 0;
        $waiting = 0;
        foreach ($stmt->fetchAll(PDO::FETCH_ASSOC) as $row) {
            if ($this->saveSnapshot((int) $row['id'], $actorId, false)) {
                $generated++;
            } else {
                $waiting++;
            }
        }
        $this->refreshRanks($sectionId);
        return ['generated' => $generated, 'waiting' => $waiting];
    }

    /** @return array{released:int} */
    public function releaseForSection(int $sectionId, int $actorId): array
    {
        $this->generateForSection($sectionId, $actorId);
        $pdo = Connection::get();
        $stmt = $pdo->prepare(
            'UPDATE official_report_cards orc
             INNER JOIN enrollments e ON e.id = orc.enrollment_id
             SET orc.released_at = NOW(), orc.released_by = ?
             WHERE e.class_section_id = ? AND e.status = "enrolled"'
        );
        $stmt->execute([$actorId, $sectionId]);
        return ['released' => $stmt->rowCount()];
    }

    /** @return list<array<string, mixed>> */
    public function cardsForSection(int $sectionId): array
    {
        $pdo = Connection::get();
        $stmt = $pdo->prepare(
            'SELECT orc.payload_json, orc.released_at, orc.issued_at, orc.honor_label, orc.section_rank
             FROM official_report_cards orc
             INNER JOIN enrollments e ON e.id = orc.enrollment_id
             INNER JOIN students s ON s.id = e.student_id
             INNER JOIN users u ON u.id = s.user_id
             WHERE e.class_section_id = ?
             ORDER BY orc.section_rank IS NULL, orc.section_rank, u.full_name'
        );
        $stmt->execute([$sectionId]);
        $out = [];
        foreach ($stmt->fetchAll(PDO::FETCH_ASSOC) as $row) {
            $card = json_decode((string) $row['payload_json'], true);
            if (!is_array($card)) {
                continue;
            }
            $card['released_at'] = $row['released_at'];
            $card['issued_at'] = $row['issued_at'];
            $card['honor'] = $row['honor_label'];
            $card['section_rank'] = $row['section_rank'] !== null ? (int) $row['section_rank'] : null;
            $out[] = $card;
        }
        return $out;
    }

    /** @return list<array<string, mixed>> */
    public function sogForSection(int $sectionId): array
    {
        $pdo = Connection::get();
        $subjects = $pdo->prepare(
            'SELECT csa.id AS csa_id, sub.title
             FROM class_subject_assignments csa
             INNER JOIN subjects sub ON sub.id = csa.subject_id
             WHERE csa.class_section_id = ?
             ORDER BY sub.title'
        );
        $subjects->execute([$sectionId]);
        $subjectRows = $subjects->fetchAll(PDO::FETCH_ASSOC);

        $students = $pdo->prepare(
            'SELECT e.id AS enrollment_id, s.lrn, s.date_of_birth, u.full_name,
                    TIMESTAMPDIFF(YEAR, s.date_of_birth, CURDATE()) AS age
             FROM enrollments e
             INNER JOIN students s ON s.id = e.student_id
             INNER JOIN users u ON u.id = s.user_id
             WHERE e.class_section_id = ? AND e.status = "enrolled"
             ORDER BY u.full_name'
        );
        $students->execute([$sectionId]);

        $gradeStmt = $pdo->prepare(
            'SELECT class_subject_assignment_id, final_rating, is_submitted
             FROM final_grades WHERE enrollment_id = ?'
        );

        $rows = [];
        foreach ($students->fetchAll(PDO::FETCH_ASSOC) as $student) {
            $gradeStmt->execute([(int) $student['enrollment_id']]);
            $byCsa = [];
            foreach ($gradeStmt->fetchAll(PDO::FETCH_ASSOC) as $g) {
                $byCsa[(int) $g['class_subject_assignment_id']] = $g;
            }
            $subjectGrades = [];
            $finals = [];
            $complete = true;
            foreach ($subjectRows as $sub) {
                $g = $byCsa[(int) $sub['csa_id']] ?? null;
                $ready = $g && (int) $g['is_submitted'] === 1 && $g['final_rating'] !== null;
                $rating = $ready ? (float) $g['final_rating'] : null;
                if ($rating !== null) {
                    $finals[] = $rating;
                } else {
                    $complete = false;
                }
                $subjectGrades[] = [
                    'title' => $sub['title'],
                    'final_rating' => $rating,
                    'submitted' => $ready,
                ];
            }
            $average = $finals ? round(array_sum($finals) / count($finals), 2) : null;
            $rows[] = [
                'enrollment_id' => (int) $student['enrollment_id'],
                'full_name' => $student['full_name'],
                'student_number' => $student['lrn'],
                'date_of_birth' => $student['date_of_birth'],
                'age' => $student['age'] !== null ? (int) $student['age'] : null,
                'subjects' => $subjectGrades,
                'general_average' => $average,
                'complete' => $complete && $subjectRows !== [],
                'honor' => $complete ? AcademicCalendar::honorLabel($average) : null,
            ];
        }

        usort($rows, static function (array $a, array $b): int {
            $av = $a['general_average'];
            $bv = $b['general_average'];
            if ($av === null && $bv === null) {
                return strcmp((string) $a['full_name'], (string) $b['full_name']);
            }
            if ($av === null) {
                return 1;
            }
            if ($bv === null) {
                return -1;
            }
            return $bv <=> $av;
        });
        $rank = 0;
        $prev = null;
        foreach ($rows as $i => &$row) {
            if ($row['general_average'] === null) {
                $row['rank'] = null;
                continue;
            }
            if ($prev === null || $row['general_average'] < $prev) {
                $rank = $i + 1;
                $prev = $row['general_average'];
            }
            $row['rank'] = $rank;
        }
        unset($row);

        return $rows;
    }

    public function saveSnapshot(int $enrollmentId, ?int $actorId, bool $release): bool
    {
        $snapshot = $this->buildSnapshot($enrollmentId);
        if ($snapshot === null) {
            return false;
        }

        $pdo = Connection::get();
        $existing = $pdo->prepare('SELECT id, card_number, released_at FROM official_report_cards WHERE enrollment_id = ? LIMIT 1');
        $existing->execute([$enrollmentId]);
        $row = $existing->fetch(PDO::FETCH_ASSOC);
        $cardNumber = $row['card_number'] ?? sprintf('HF-%s-%04d', date('Y'), $enrollmentId);
        $snapshot['card_number'] = $cardNumber;
        $snapshot['issued_at'] = date('c');
        if ($release || !empty($row['released_at'])) {
            $snapshot['released_at'] = date('c');
        }
        $json = json_encode($snapshot, JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES);
        $honor = $snapshot['honor'] ?? null;

        if ($row) {
            $sql = 'UPDATE official_report_cards
                    SET general_average = ?, remarks = ?, honor_label = ?, payload_json = ?, issued_at = NOW(), generated_by = ?';
            $params = [
                $snapshot['general_average'],
                $snapshot['remarks'],
                $honor,
                $json,
                $actorId,
            ];
            if ($release && empty($row['released_at'])) {
                $sql .= ', released_at = NOW(), released_by = ?';
                $params[] = $actorId;
            }
            $sql .= ' WHERE id = ?';
            $params[] = $row['id'];
            $pdo->prepare($sql)->execute($params);
        } else {
            $pdo->prepare(
                'INSERT INTO official_report_cards
                 (enrollment_id, school_year_id, card_number, general_average, remarks, honor_label, payload_json, issued_at, generated_by, released_at, released_by)
                 VALUES (?, ?, ?, ?, ?, ?, ?, NOW(), ?, ?, ?)'
            )->execute([
                $enrollmentId,
                $snapshot['student']['school_year_id'],
                $cardNumber,
                $snapshot['general_average'],
                $snapshot['remarks'],
                $honor,
                $json,
                $actorId,
                $release ? date('Y-m-d H:i:s') : null,
                $release ? $actorId : null,
            ]);
        }
        return true;
    }

    private function refreshRanks(int $sectionId): void
    {
        $pdo = Connection::get();
        $stmt = $pdo->prepare(
            'SELECT orc.id, orc.general_average, orc.payload_json
             FROM official_report_cards orc
             INNER JOIN enrollments e ON e.id = orc.enrollment_id
             WHERE e.class_section_id = ?
             ORDER BY orc.general_average DESC, orc.id'
        );
        $stmt->execute([$sectionId]);
        $rows = $stmt->fetchAll(PDO::FETCH_ASSOC);
        $rank = 0;
        $prev = null;
        $upd = $pdo->prepare('UPDATE official_report_cards SET section_rank = ?, honor_label = ?, payload_json = ? WHERE id = ?');
        foreach ($rows as $i => $row) {
            $avg = (float) $row['general_average'];
            if ($prev === null || $avg < $prev) {
                $rank = $i + 1;
                $prev = $avg;
            }
            $honor = AcademicCalendar::honorLabel($avg);
            $payload = json_decode((string) $row['payload_json'], true);
            if (is_array($payload)) {
                $payload['section_rank'] = $rank;
                $payload['honor'] = $honor;
            }
            $upd->execute([
                $rank,
                $honor,
                is_array($payload) ? json_encode($payload, JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES) : $row['payload_json'],
                $row['id'],
            ]);
        }
    }

    private function allSubjectsSubmitted(int $enrollmentId): bool
    {
        foreach ($this->subjectStatus($enrollmentId) as $sub) {
            if (!$sub['ready']) {
                return false;
            }
        }
        return $this->subjectStatus($enrollmentId) !== [];
    }

    /** @return list<array{title:string, ready:bool}> */
    private function subjectStatus(int $enrollmentId): array
    {
        $pdo = Connection::get();
        $stmt = $pdo->prepare(
            'SELECT sub.title,
                    fg.final_rating, fg.is_submitted
             FROM enrollments e
             INNER JOIN class_subject_assignments csa ON csa.class_section_id = e.class_section_id
             INNER JOIN subjects sub ON sub.id = csa.subject_id
             LEFT JOIN final_grades fg ON fg.enrollment_id = e.id AND fg.class_subject_assignment_id = csa.id
             WHERE e.id = ?
             ORDER BY sub.title'
        );
        $stmt->execute([$enrollmentId]);
        $out = [];
        foreach ($stmt->fetchAll(PDO::FETCH_ASSOC) as $row) {
            $out[] = [
                'title' => (string) $row['title'],
                'ready' => (int) ($row['is_submitted'] ?? 0) === 1 && $row['final_rating'] !== null,
            ];
        }
        return $out;
    }

    /** @return array<string, mixed>|null */
    private function buildSnapshot(int $enrollmentId): ?array
    {
        $pdo = Connection::get();
        $head = $pdo->prepare(
            'SELECT e.id AS enrollment_id, e.class_section_id,
                    s.id AS student_id, s.lrn, s.grade_level, s.section_code, s.school_year_id, s.date_of_birth,
                    TIMESTAMPDIFF(YEAR, s.date_of_birth, CURDATE()) AS age,
                    u.full_name, st.code AS strand_code, st.name AS strand_name, sy.label AS school_year,
                    adv.full_name AS adviser_name
             FROM enrollments e
             INNER JOIN students s ON s.id = e.student_id
             INNER JOIN users u ON u.id = s.user_id
             INNER JOIN strands st ON st.id = s.strand_id
             INNER JOIN school_years sy ON sy.id = s.school_year_id
             INNER JOIN class_sections cs ON cs.id = e.class_section_id
             LEFT JOIN teachers t ON t.id = cs.adviser_teacher_id
             LEFT JOIN users adv ON adv.id = t.user_id
             WHERE e.id = ?
             LIMIT 1'
        );
        $head->execute([$enrollmentId]);
        $student = $head->fetch(PDO::FETCH_ASSOC);
        if (!$student) {
            return null;
        }

        $gradeLevel = (int) $student['grade_level'];
        $calendar = AcademicCalendar::forGrade($gradeLevel);

        $subs = $pdo->prepare(
            'SELECT sub.subject_code, sub.title,
                    fg.q1, fg.q2, fg.q3, fg.q4, fg.sem1, fg.sem2, fg.final_rating, fg.action_taken, fg.is_submitted
             FROM class_subject_assignments csa
             INNER JOIN subjects sub ON sub.id = csa.subject_id
             LEFT JOIN final_grades fg ON fg.class_subject_assignment_id = csa.id AND fg.enrollment_id = ?
             WHERE csa.class_section_id = ?
             ORDER BY sub.title'
        );
        $subs->execute([$enrollmentId, (int) $student['class_section_id']]);
        $subjects = [];
        $finals = [];
        foreach ($subs->fetchAll(PDO::FETCH_ASSOC) as $row) {
            if ((int) ($row['is_submitted'] ?? 0) !== 1 || $row['final_rating'] === null) {
                return null;
            }
            $final = (float) $row['final_rating'];
            $finals[] = $final;
            $periods = [];
            foreach ($calendar['periods'] as $period) {
                $key = 'q' . $period['id'];
                $periods[] = [
                    'id' => $period['id'],
                    'code' => $period['code'],
                    'label' => $period['label'],
                    'grade' => $this->num($row[$key] ?? null),
                ];
            }
            $subjects[] = [
                'subject_code' => $row['subject_code'],
                'title' => $row['title'],
                'q1' => $this->num($row['q1']),
                'q2' => $this->num($row['q2']),
                'sem1' => $calendar['mode'] === 'semesters' ? $this->num($row['sem1']) : null,
                'q3' => $this->num($row['q3']),
                'q4' => $calendar['mode'] === 'semesters' ? $this->num($row['q4']) : null,
                'sem2' => $calendar['mode'] === 'semesters' ? $this->num($row['sem2']) : null,
                'periods' => $periods,
                'final_rating' => $final,
                'action_taken' => $row['action_taken'],
            ];
        }
        if ($subjects === []) {
            return null;
        }

        $average = round(array_sum($finals) / count($finals), 2);
        $passing = $this->passingMark();
        $honor = AcademicCalendar::honorLabel($average);
        return [
            'school' => [
                'name' => 'HOLY FACE OF JESUS LYCEUM OF SAN JOSE, INC.',
                'short_name' => 'Holy Face',
                'address' => 'R & J Bldg., Blk 09, Lot 6 & 8, Mayon Ave., Amityville, San Jose, Rodriguez, Rizal, Philippines',
                'logo' => 'https://www.holyface.school/assets/img/branding/hf-logo.png',
            ],
            'student' => [
                'full_name' => $student['full_name'],
                'student_number' => $student['lrn'],
                'strand_code' => $student['strand_code'],
                'strand_name' => $student['strand_name'],
                'grade_level' => $gradeLevel,
                'section_code' => $student['section_code'],
                'school_year' => $student['school_year'],
                'school_year_id' => (int) $student['school_year_id'],
                'date_of_birth' => $student['date_of_birth'],
                'age' => $student['age'] !== null ? (int) $student['age'] : null,
                'adviser_name' => $student['adviser_name'],
            ],
            'calendar' => $calendar,
            'subjects' => $subjects,
            'general_average' => $average,
            'remarks' => $average >= $passing ? 'PASSED' : 'FAILED',
            'honor' => $honor,
            'passing_mark' => $passing,
        ];
    }

    private function num(mixed $v): ?float
    {
        return $v === null || $v === '' ? null : (float) $v;
    }

    private function passingMark(): float
    {
        try {
            $v = Connection::get()->query(
                "SELECT setting_value FROM grading_settings WHERE setting_key = 'passing_mark' LIMIT 1"
            )->fetchColumn();
            if ($v !== false && $v !== null && $v !== '') {
                return (float) $v;
            }
        } catch (\Throwable) {
            // settings table may be missing on older installs
        }
        return 75.0;
    }
}
